five=inp==5; six=inp==6
keep=(out==6)  # 6s that stayed
def colcount(i,j): return five[:,j].sum()
def rowcount(i,j): return five[i,:].sum()
ks=list(zip(*np.where(keep)))
print('kept 6 cells:',len(ks))
print('row5 counts at kept:',sorted(set(rowcount(*k) for k in ks)))
print('col5 counts at kept:',sorted(set(colcount(*k) for k in ks)))
print('row5 counts at nonkept 6:',sorted(set(rowcount(*k) for k in zip(*np.where(six&~keep)))))
print('col5 counts at nonkept 6:',sorted(set(colcount(*k) for k in zip(*np.where(six&~keep)))))
# test: keep iff row5cnt>=a and col5cnt>=b
for a in range(0,8):
  for b in range(0,8):
    pred=np.array([[rowcount(i,j)>=a and colcount(i,j)>=b for j in range(25)] for i in range(23)])&six
    if np.array_equal(pred,keep): print('MATCH',a,b)

def show(a):
    for r in a.astype(str).tolist(): print(''.join(r))
print('INPUT (5=#):'); show(inp)
print('OUTPUT (kept6 shown as 6):'); show(out)

from collections import Counter
keep=(out==6)&six
sigK=Counter(); sigN=Counter()
def sig(i,j):
    return tuple(five[max(0,i-1):i+2, max(0,j-1):j+2].astype(int).flatten())
for i,j in zip(*np.where(keep)): sigK[sig(i,j)]+=1
for i,j in zip(*np.where(six&~keep)): sigN[sig(i,j)]+=1
print('signatures only in kept:')
for s,c in sigK.items():
    if sigN[s]==0: print(np.array(s).reshape(3,3),c)
print('overlap sigs:',sum(c for s,c in sigK.items() if sigN[s]>0))

